# Detailed comparison: check each type for discrepancies
meas = snapshot["dependency_concentration"]["measurement"]
total = len(workers)

types_to_check = {
    "engine": lambda w: w["engine"],
    "trigger": lambda w: w["trigger"],
    "effect": lambda w: w["effect"],
    "digest": lambda w: next((e["digest"] for e in w.get("version_history",[]) if e.get("version")==w.get("current_version")), None),
}

all_match = True
for dtype, fn in types_to_check.items():
    recomputed = collections.Counter(fn(w) for w in workers)
    established = {e["identity"]: e["worker_count"] for e in meas["by_type"].get(dtype, [])}

    # Check all recomputed keys
    for ident, cnt in recomputed.items():
        est_cnt = established.get(ident, 0)
        if cnt != est_cnt:
            print(f"MISMATCH [{dtype}] {ident}: recomputed={cnt}, established={est_cnt}")
            all_match = False

    # Check for keys in established but not recomputed
    for ident, cnt in established.items():
        if ident not in recomputed:
            print(f"EXTRA in established [{dtype}] {ident}: established={cnt}, not found in recomputation")
            all_match = False

if all_match:
    print("ALL MATCH - measurement is consistent with underlying records")

# Also verify fleet_share values
print("\n=== Fleet share verification ===")
for dtype, fn in types_to_check.items():
    recomputed = collections.Counter(fn(w) for w in workers)
    established_list = meas["by_type"].get(dtype, [])
    for e in established_list:
        ident = e["identity"]
        recomputed_share = recomputed.get(ident, 0) / total
        est_share = e["fleet_share"]
        if abs(recomputed_share - est_share) > 0.000001:
            print(f"SHARE MISMATCH [{dtype}] {ident}: recomputed={recomputed_share:.6f}, established={est_share}")
        else:
            pass  # matches

print("Share verification complete.")

import collections

workers = snapshot["workers"]

# Engine -> workers detail
engine_to_workers = collections.defaultdict(list)
for w in workers:
    engine_to_workers[w["engine"]].append(w["name"])

print("=== ENGINE -> WORKER COUNT ===")
for engine, names in sorted(engine_to_workers.items(), key=lambda x: -len(x[1])):
    print(f"\n{engine} ({len(names)} workers):")
    tasks = collections.Counter()
    for n in names:
        for w in workers:
            if w["name"] == n:
                tasks[w["task"]] += 1
    print(f"  Tasks: {dict(tasks)}")
    print(f"  Workers: {', '.join(names[:5])}{'...' if len(names)>5 else ''}")

# Check if all enrichment workers share the same readable_model
enrichment_models = set()
for w in workers:
    if w["engine"] == "enrichment/harness/execute_enrichment.py":
        model = tuple(w.get("readable_model", []))
        enrichment_models.add(model)

print(f"\nDistinct readable_models among enrichment workers: {len(enrichment_models)}")
if len(enrichment_models) == 1:
    print("ALL 60 enrichment workers share identical model logic")

# Digest -> task types
digest_to_tasks = collections.defaultdict(lambda: collections.Counter())
for w in workers:
    vh = w.get("version_history", [])
    cv = w.get("current_version")
    digest = None
    for entry in vh:
        if entry.get("version") == cv:
            digest = entry.get("digest")
            break
    digest_to_tasks[digest][w["task"]] += 1

print("\n=== DIGEST -> TASK TYPES ===")
for digest, task_counts in digest_to_tasks.items():
    print(f"{digest}: {dict(task_counts)}")

